+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.75rem;
+  line-height: 1.55;
+}
+
+.close {
+  display: grid;
+  flex: none;
+  width: 32px;
+  height: 32px;
+  place-items: center;
+  border: 1px solid var(--thorp-line-strong);
+  border-radius: 5px;
+  background: transparent;
+  color: var(--thorp-copy);
+  cursor: pointer;
+}
+
+.close:hover {
+  border-color: var(--thorp-accent-soft);
+  color: var(--thorp-foreground);
+}
+
+.close:focus-visible {
+  outline: var(--thorp-focus-outline);
+  outline-offset: var(--thorp-focus-offset-compact);
+}
+
+.badges {
+  display: flex;
+  gap: 6px;
+  flex-wrap: wrap;
+}
+
+.status,
+.validation,
+.retry {
+  padding: 2px 7px;
+  border: 1px solid var(--thorp-line-strong);
+  border-radius: 3px;
+  color: var(--thorp-copy);
+  font-size: 0.63rem;
+  font-weight: 700;
+}
+
+.validation {
+  border-color: var(--thorp-warning);
+  color: var(--thorp-warning);
+}
+
+.rows {
+  display: grid;
+  gap: 0;
+  margin: 0;
+}
+
+.rows div {
+  display: grid;
+  grid-template-columns: 128px minmax(0, 1fr);
+  gap: 12px;
+  padding: 11px 0;
+  border-bottom: 1px solid var(--thorp-line);
+}
+
+.rows div:first-child {
+  border-top: 1px solid var(--thorp-line);
+}
+
+.rows dt {
+  color: var(--thorp-muted);
+  font-size: 0.72rem;
+}
+
+.rows dd {
+  display: grid;
+  gap: 3px;
+  margin: 0;
+  font-size: 0.84rem;
+  font-variant-numeric: tabular-nums;
