+  margin: 0;
+  color: var(--thorp-accent-soft);
+  font-size: 0.86rem;
+  font-weight: 700;
+}
+
+.reasonText {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.74rem;
+  line-height: 1.6;
+}
+
+.runId {
+  margin: 0;
+  color: var(--thorp-muted);
+  font-size: 0.7rem;
+}
+
+.runId code {
+  overflow-wrap: anywhere;
+  color: var(--thorp-copy);
+  font-family: var(--thorp-font-mono);
+}
+
+@media (max-width: 560px) {
+  .rows div {
+    grid-template-columns: minmax(0, 1fr);
+    gap: 5px;
+  }
+}

